+@implements IDisposable
+@inject IAddressValidator AddressValidator
+
+<h3>Shipping Information</h3>
+
+<div class="shipping-form">
+    <label>
+        Name
+        <input @bind="Shipping.Name" @bind:event="oninput" disabled="@_isValidating" />
+    </label>
+
+    <label>
+        Address
+        <input @bind="Shipping.Address" @bind:event="oninput" disabled="@_isValidating" />
+    </label>
+
+    <label>
+        City
+        <input @bind="Shipping.City" @bind:event="oninput" disabled="@_isValidating" />
+    </label>
+
+    <label>
+        Zip Code
+        <input @bind="Shipping.ZipCode" @bind:event="oninput" disabled="@_isValidating" />
+    </label>
+
+    @if (!string.IsNullOrEmpty(_validationError))
+    {
+        <p class="validation-error" role="alert">@_validationError</p>
+    }
+
+    <button @onclick="HandleNext" disabled="@_isValidating">
+        @if (_isValidating)
+        {
+            <span class="spinner" aria-hidden="true"></span>
+            <span>Validating…</span>
+        }
+        else
+        {
+            <span>Next</span>
+        }
+    </button>
+</div>
+
+@code {
+    private CancellationTokenSource? _cts;
+    private bool _isValidating;
+    private string? _validationError;
+
+    [Parameter, EditorRequired]
+    public ShippingInfo Shipping { get; set; } = default!;
+
+    [Parameter]
+    public EventCallback OnNext { get; set; }
+
+    private async Task HandleNext()
+    {
+        _validationError = null;
+
+        // Cancel any in-flight validation (e.g. user went back, changed fields, clicked Next again).
+        CancelPendingValidation();
+
+        _cts = new CancellationTokenSource();
+        var token = _cts.Token;
+
+        _isValidating = true;
+
+        try
+        {
+            var isValid = await AddressValidator.ValidateAddressAsync(
+                Shipping.Address, Shipping.City, Shipping.ZipCode, token);
+
+            token.ThrowIfCancellationRequested();
+
+            if (isValid)
+            {
+                await OnNext.InvokeAsync();
+            }
+            else
+            {
+                _validationError = "The address could not be verified. Please check and try again.";
+            }
+        }
+        catch (OperationCanceledException)
+        {
+            // Validation was cancelled — nothing to do.
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    private void CancelPendingValidation()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+
+    public void Dispose()
+    {
+        CancelPendingValidation();
+    }
+}
